    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Agostinho diz que, antes de saber por que orar, você precisa se reconhecer 'desolado' neste mundo e enxergar que os afetos do seu coração estão 'desordenados' — o que deveria ser amado em primeiro lugar ocupando um terceiro ou quarto lugar. Olhando com sinceridade para sua vida de oração, quais coisas boas (segurança financeira, status, aprovação, conforto) têm ocupado em seu coração o lugar que pertence a Deus, fazendo de suas orações 'preocupação voltada na direção de Deus' em vez de descanso?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Provérbios 30 ('não me dê nem pobreza nem riquezas') foi apresentado por Agostinho como o 'teste' da motivação por trás de um pedido legítimo: pedir o suprimento, mas só na medida em que não prejudique colocar Deus em primeiro lugar. Pense em algo concreto que você tem pedido a Deus — como ficaria esse mesmo pedido se você o reorientasse pela oração de Provérbios 30?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Lutero ensinava a transformar um texto bíblico numa 'guirlanda de quatro cordões' — instrução, ação de graças, confissão e oração — e a interromper o roteiro quando o Espírito Santo 'começa a pregar' ao coração. Como seria, na prática desta semana, levar um único versículo por esses quatro movimentos em vez de apenas estudá-lo, e o que costuma impedir você de parar para ouvir quando algo no texto toca fundo?$p$, 'reflexao', null);
  end if;

  -- ---------------------------------------------------------------
  -- Capítulo 7 — Regras para a oração  (aula ordem = 8)
