    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$O capítulo abre alertando para 'o perigo da familiaridade': a Oração do Senhor virou ruído de fundo, como o trem que o morador já nem percebe. Que palavra ou petição do Pai Nosso você repete há tanto tempo que parou de ouvir de verdade — e o que aconteceria se você a orasse devagar, como se fosse a primeira vez?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Os três mestres mostram que as três primeiras petições ('santificado seja o teu nome', 'venha o teu reino', 'seja feita a tua vontade') vêm de propósito antes de pedirmos pão, perdão e livramento, porque a adoração centrada em Deus cura o egocentrismo e reordena nossa visão antes de chegarmos às nossas necessidades. Como costuma ser a 'ordem' das suas orações — você começa correndo para seus pedidos, ou dá primazia a contemplar e honrar a Deus, e que diferença isso faz no resto da oração?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Calvino lembra que a Oração do Senhor nos foi dada no plural ('dá-nos', 'perdoa-nos', 'livra-nos'), e Lewis acrescenta que é preciso uma comunidade para conhecer alguém — orando juntos enxergamos facetas de Jesus que sozinhos não veríamos. Quanto da sua vida de oração é solitária, e onde poderia começar a orar de fato com outras pessoas, levando a sério esse 'nós' do Pai Nosso?$p$, 'reflexao', null);
  end if;

