    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Keller diz que o louvor é a 'oração alfa' que corrige e motiva as outras formas de oração, citando aquela mulher que parou de correr para a lista de pedidos e passou a começar lembrando da bondade de Deus. Quando você senta para orar, o que costuma vir primeiro: a sua lista de necessidades ou o louvor por quem Deus é? Como seria reordenar isso na sua prática esta semana?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Agostinho ensina que 'somos aquilo que amamos' e que nossa miséria nasce de amarmos algo mais do que a Deus, esmagando esse objeto sob o peso das nossas expectativas. Que afeto desordenado você reconhece hoje no seu coração, e como o louvor poderia começar a reordenar esse amor?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Keller fala do pecado da ingratidão como 'plágio cósmico' — ficar com o crédito por aquilo que nos foi dado, vivendo na ilusão de autossuficiência. Em que área da sua vida você tem dado pouca graça a Deus ultimamente, assumindo como mérito seu algo que recebeu das mãos dele?$p$, 'reflexao', null);
  end if;

