    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Keller mostra que perder de vista a gratuidade do perdão leva à culpa e ao autodesprezo, mas perder de vista o preço dele leva a uma confissão superficial que não muda nada. Para qual dos dois erros você tende mais, e como isso tem moldado o jeito que você confessa seus pecados a Deus?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O homem que sofria por um caso antigo só encontrou alívio quando pediu perdão também pelo seu 'coração endurecido', e não apenas pelo ato. Quando você se arrepende, você costuma chegar às atitudes e desejos por trás do pecado, ou para na superfície do comportamento? O que mudaria se você levasse a confissão até a raiz?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Seguindo Owen, Keller distingue parar de pecar por medo das consequências de rejeitar o pecado por amor a Deus — vendo-o como odioso porque desonra aquele que morreu por nós. Pegue um pecado recorrente seu: o que tem te movido a lutar contra ele, o medo da dor que ele causa ou o amor por Cristo? Como seria 'pregar ao próprio coração' a graça de Jesus nessa luta?$p$, 'reflexao', null);
  end if;

