    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Keller adverte contra dois extremos na súplica: pedir de forma manipuladora, dizendo a Deus 'seja feita a minha vontade', ou se acanhar demais e quase não pedir nada. Para qual desses dois lados a sua oração de pedido tem pendido, e o que isso revela sobre como você enxerga a Deus?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Packer sugere 'discutir' com Deus — apresentar a ele os motivos pelos quais aquilo que pedimos nos parece o melhor, à luz do que sabemos das Escrituras, e ainda dizer com sinceridade que, se ele quiser algo diferente, isso é que de fato queremos. Pense num pedido que você carrega com desespero: você conseguiria orar assim, entregando-o à sabedoria dele? O que dentro de você resiste a essa entrega?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Keller diz que a oração sem resposta de Jesus no Getsêmani garante que as nossas serão ouvidas — ele recebeu o silêncio que merecíamos para que recebêssemos a resposta que ele merece. Diante de uma oração sua que parece não ter sido respondida, como muda a sua confiança saber que Deus não deixou Jesus sem resposta por acaso, mas em seu favor?$p$, 'reflexao', null);
