  -- ---------------------------------------------------------------
  -- Capítulo 15 — Prática: a oração diária  (aula ordem = 16)
  -- ---------------------------------------------------------------
  select id into v_aula_id from public.aulas
  where curso_id = v_curso_id and ordem = 16;

  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (
      v_curso_id,
      $t$Capítulo 15 — Prática: a oração diária$t$,
      16,
$conteudo$Uma história de oração diária aulo disse que deveríamos “orar sem cessar” (1Ts 5.17) querendo dizer que, P se possível, precisamos fazer tudo, todo os dias, tendo Deus em mente (1Co 10.31). Em cada episódio do nosso dia deve soar uma música de fundo de gratidão e alegria captada somente por nossos ouvidos (Cl 3.16,17). Esse tipo de oração espontânea e constante ao longo do dia deve ser um hábito do coração. Jamais o desenvolveremos, no entanto, se não adotarmos a disciplina da oração regular e diária. A oração diária é uma prática bíblica desde tempos imemoriais. “Três vezes por dia [Daniel] se ajoelhava e orava, dando graças a Deus” (Dn 6.10). Dizia-se que a prática cristã medieval da horae canonicae, liturgia organizada em horários fixos e diários de oração — também chamada em Ofício Divino —, fundamentava-se no desafio lançado por Jesus aos discípulos adormecidos: “Não fostes capazes de vigiar comigo nem uma hora?” (Mt 26.40). Nos monastérios, oficiavam-se múltiplas cerimônias de oração diária. No entanto, Alan Jacobs argumenta que os oito períodos fixos do dia para a oração monástica — matinas (meia-noite), laudes (3 da manhã), prima (6 da manhã), terça (9 da manhã), sexta (meio-dia), noa (3 da tarde), vésperas (6 da tarde) e completas (9 da noite) — com o tempo se revelaram fisicamente insuportáveis. Muitas ordens monásticas diminuíram o número de cerimônias ou distribuíram a responsabilidade por esses vários períodos de oração entre diferentes irmãos e irmãs.1 Quando a Reforma Protestante chegou à Grã-Bretanha, o reformador Thomas Cranmer precisou enfrentar a questão de como ajudar pessoas comuns, com um dia cheio de trabalho, a fazerem suas orações diárias. Preocupou-se também com o fato de as práticas de oração medievais, tão amarradas a um calendário litúrgico de dias santos extremamente detalhado, fornecerem às pessoas apenas fragmentos de passagens bíblicas curtas e diárias a serem usadas nesses dias. Ele acreditava que isso as impedia de se familiarizarem com a Bíblia inteira. Em seu prefácio ao primeiro Livro de Oração Comum de 1549, Cranmer defendeu a ideia de que os antigos pais se certificavam de que “toda a Bíblia (ou a maior parte dela) deveria ser lida uma vez por ano” nos cultos regulares e nas orações da igreja.2 A solução que ele encontrou foi, primeiro, eliminar os vários períodos de oração ao longo do dia, exceto a oração da manhã (matinas) e a da tarde. Em seguida forneceu, bem no início do seu livro de oração, um “cronograma” segundo o qual quatro capítulos da Bíblia deviam ser lidos todos os dias — dois na oração da manhã e dois na da tarde. Como Cranmer observa em sua introdução ao cronograma de leitura da Bíblia, isso significa que o Antigo Testamento inteiro seria lido uma vez e o Novo Testamento, duas vezes em um ano, exceto os capítulos de genealogias, partes de Levítico e partes do livro do Apocalipse.3 Além disso, Cranmer prescreveu a imersão em Salmos. Isso também foi uma adaptação da prática clerical para leigos. Enquanto os monges, com suas cerimônias diárias, eram capazes de percorrer o livro de Salmos toda semana, Cramner delineou um cronograma segundo o qual todos os 150 salmos poderiam ser lidos pela manhã e à noite e finalizados em um mês.4 O resultado foi a brilhante revisão de um modelo antigo. Ele criou um Ofício Divino protestante com um foco maior na leitura sistemática das Escrituras. Demandava duas orações diárias, que podiam ser conduzidas tanto em comunidade quanto em particular. Oferecia orações escritas de adoração, de confissão e de ações de graças, espaço para orações de petição em forma livre, além de um plano para a leitura sequêncial dos livros da Bíblia, o qual tem sido chamado de lectio continua. A “protestantização” da oração diária também foi experimentada por igrejas não anglicanas, embora presbiterianos, congregacionalistas e outros colocassem menor ênfase do que Cranmer nas orações escritas. João Calvino, contudo, preparou cinco modelos simples de orações breves a serem utilizados em cada uma das cinco vezes do dia em que aconselhava os cristãos a orarem,5 conclamando-os a oferecerem orações “quando nos levantamos pela manhã, antes de darmos início ao trabalho diário, quando nos sentamos para comer, depois de acabarmos a refeição pela graça de Deus e quando nos preparamos para nos recolher”.6 Por sua vez, a maioria das igrejas protestantes decidiu adotar como padrão uma oração matutina individual e uma oração noturna em família. O famoso calendário de leitura bíblica anual do ministro presbiteriano Robert Murray M’Cheyne, desenvolvido no início do século 19 na Escócia, incluía dois capítulos de manhã, acompanhando a oração individual, e dois à noite, para acompanhar a oração em família.7 Somando-se a isso, as igrejas reformadas livres praticavam o cântico congregacional de algum salmo no lugar da leitura matutina e noturna do saltério, a fim de inculcar o livro de Salmos no coração e na mente do povo.8 Em tempos mais recentes, a prática de uma “hora silenciosa” única e diária foi considerada obrigatória durante duas ou três gerações de estudantes universitários cristãos. Nas décadas de 1930 e 1940, líderes evangélicos britânicos e australianos produziram um pequeno livreto intitulado Quiet time: a practical guide for daily devotions [Hora silenciosa: um guia prático para devoções diárias]. A obra foi publicada pela primeira vez nos Estados Unidos, em 1945, pela InterVarsity Press.9 O livreto de 30 páginas viria a se tornar um sucesso, vendendo um milhão de cópias, além de haver moldado e influenciado no mínimo por 50 anos os livros e guias evangélicos que surgiram depois dele.10 Quiet time dedica boa parte de suas poucas páginas a insistir em que a devoção diária é uma disciplina que requer um ato de vontade bastante deliberado. Aconselha a encontrarmos um lugar tranquilo e a acalmarmos nosso espírito com o pensamento de que o próprio Deus busca um encontro conosco. Instruinos a usar um diário para anotar os resultados do nosso estudo bíblico, após o qual devemos finalizar com uma quantidade de tempo de oração mais ou menos equivalente. O único período de tempo especificado é 20 minutos, considerado mínimo. No meio da parte mais prática de Quiet time há um resumo de algumas das práticas de oração de George Mueller (1805-1898), célebre ministro alemão batista e fundador de orfanatos, que passou a maior parte da vida na Inglaterra. Mueller ficou famoso por sua vida de oração, sobre a qual escreveu em alguns textos autobiográficos. Preocupava-se particularmente em meditar nas Escrituras como forma de advertir o próprio coração e levá-lo à oração. Nesse aspecto, Mueller seguia a orientação de Martinho Lutero. Seu método de meditação também era um clássico. Ele tinha um conjunto de perguntas que propunha para qualquer texto, ecoando as de Lutero. Quiet time lhes confere notoriedade ao relacioná-las:

Há no texto algum exemplo para eu seguir? Há alguma ordem para eu obedecer? Há algum erro para eu evitar? Há algum pecado para eu abandonar? Há alguma promessa para eu reivindicar? Há alguma ideia nova sobre o próprio Deus?11

Após o estudo bíblico e a meditação, a oração é inicialmente formulada como um aproximar-se de Deus em confissão dos nossos pecados e, depois, como uma resposta de agradecimento e louvor por nossa salvação pela cruz. Após o louvor vêm a intercessão por outras pessoas e, por fim, a petição pelas próprias necessidades.12

Praticando a oração diária hoje A hora silenciosa praticada no fim do século 20 tendia a minimizar os aspectos mais experienciais da oração. Enfatizava-se o estudo bíblico interpretativo, o qual incluía o esboço de uma passagem bíblica, a respectiva paráfrase e a busca pelas estruturas literárias de composição. Um devocional diário nos convidava a perguntar a cada passagem: “Existe algum pensamento recorrente ilustrado pela utilização repetida de uma mesma palavra, expressão, termo ou ideia contrastante? [...] Qual a orientação da passagem — do particular para o genérico ou do genérico para o particular — ao tratar do assunto abordado?”.13 Isso requer muita prática, e é difícil imaginar que alguém consiga fazê-lo em pouquíssimos minutos a cada manhã. O propósito era fomentar um método de estudo bíblico indutivo diário voltado mais para a interpretação do texto do que para a meditação e a experiência com Deus. Depois dessa espécie de estudo bíblico, vinha a oração, mas o estudo de caráter mais cognitivo não conduzia com grande naturalidade à adoração. Portanto, a oração era dominada por petições em favor de necessidades e pela confissão de pecados. Muitos consideram a hora silenciosa evangélica tradicional — com sua ênfase no estudo bíblico interpretativo e na oração de petição — um exercício racional demais. Em reação a isso e desejosos de uma experiência maior com Deus, muitos protestantes têm se voltado para tradições mais católicas e ortodoxas orientais, incluindo a lectio divina, a oração contemplativa e as horas fixas de oração litúrgica. Uma das revisões contemporâneas mais bem-sucedidas da antiga oração em horários fixos são os livros de Phyllis Tickle, The divine hours [As horas divinas]. Tickle dispõe convenientemente na mesma página uma leitura breve dos Salmos e das Escrituras, versos de hinos, declarações e orações, propiciando uma referência mais fácil do que os guias de Ofício Divino tradicionais oferecem. Contudo, seu trabalho resiste a diversas das inovações protestantes de Cranmer para a oração diária. Ela defende de três a quatro períodos diários de oração em vez de dois e afasta-se da leitura bíblica sistemática e sequencial associada a Cranmer, Calvino e outras igrejas da Reforma.14 Todavia, o estímulo de Tickle para as orações escritas não contraria a prática reformada. Embora alguns ministros não anglicanos, como John Bunyan, se opusessem com veemência a todas as formas escritas de oração,15 outros contemporâneos de Bunyan, como John Owen, acreditavam que as formas de oração prescritas podiam ser úteis se redigidas por “pessoas [piedosas] com base em experiências próprias e à luz das Escrituras”.16 Tais orações podem comover o coração e servir de estímulo e direção para nossas próprias orações.17 Ainda compete a cada um de nós, portanto, a tarefa de encontrar formas de praticar a oração e a devoção diárias. Em geral, creio que precisamos ir além da prática devocional evangélica do século 20, bem como da atual tendência de restauração de formas de oração medievais. Nenhum leitor deste livro se surpreenderá, a essa altura, ao me ouvir dizer que, a meu ver, poderíamos aprender mais com as práticas de oração dos teólogos protestantes dos séculos 16, 17 e 18. Olhando para trás, para esses autores, como fiz por todo este livro, detecto várias mudanças importantes a serem implementadas. Creio que a oração deveria ser mais frequente do que a clássica prática da hora silenciosa uma vez ao dia. Como vimos, Lutero acreditava que se devia orar duas vezes ao dia, enquanto Calvino aconselhava que a oração fosse breve e ainda mais frequente. Pensando em um dia inteiro, parece haver unanimidade em todos os ramos do passado cristão de que deveríamos voltar nossos pensamentos a Deus em momentos determinados e mais do que uma vez ao longo de um período de 24 horas. Concordo com a maioria das igrejas protestantes que duas vezes ao dia é bom, embora não possamos insistir demais num cronograma único. Pessoalmente, considero que as orações da manhã e do começo da noite funcionam melhor no meu caso, mas também tento às vezes praticar, ao meiodia, um curto período, “em pé”, de oração focada para me reconectar com os insights da oração da manhã. Creio que a oração diária deveria ser mais bíblica, isto é, mais fundamentada na leitura e no estudo bíblicos sistemáticos, bem como na meditação disciplinada sobre as passagens. Já expus minhas razões para essa convicção em detalhes por todo este livro. O plano anual de leitura da Bíblia proposto por Cranmer não consta mais dos Livros de Oração Comum mais usados mundo afora, mas pode ser encontrado em reimpressões das obras de 1549 e 1552. O calendário de leitura da Bíblia de M’Cheyne, facilmente encontrado em vários formatos na internet e em outros lugares, conduz o leitor pela Bíblia em diversos ritmos, dependendo do seu tempo disponível para dedicar à atividade. Em todo caso, a leitura sistemática e sequencial da Bíblia deve preceder ou acompanhar a oração. A oração diária individual, em privado, deve ser mais interligada à oração coletiva da igreja. Calvino queria que os cristãos aprendessem a oração privada por meio das orações públicas e do cântico conjunto dos salmos como adoração.18 Lutero escreveu que orava duas vezes ao dia, apressando-se para o quarto “ou, sendo a hora e o dia apropriados, rumo à igreja, onde há uma congregação reunida”.19 Isso mostra como era importante para os grandes mestres da igreja que nossa vida de oração não acontecesse só em privado. É certo e necessário aprendermos a orar não apenas a partir da leitura dos Salmos e do restante da Bíblia, mas também escutando e lendo as orações da igreja. Hoje, muitas igrejas, em especial as que adotam o chamado louvor contemporâneo, quase não oferecem aos congregantes ajuda alguma com a oração nesse sentido. As únicas orações que eles ouvem são expressões “espontâneas” dos líderes de louvor, ou a oração do pregador ao término do sermão. Orações testadas pelo tempo e pensadas com grande cuidado não são apresentadas como acontecia no passado. Assim, muitos cristãos de hoje têm de procurá-las, e é aqui que as incomparáveis “compilações” de Cranmer, bem como outros recursos, como as obras The divine hours [Horas divinas], de Phyllis Tickle, ou The valley of vision [O vale da visão], de Arthur Bennett, podem ser úteis.20 Por fim, a oração diária deve incluir a meditação, não só o estudo da Bíblia, e no geral devemos nutrir muito mais expectativas de experiência em sentido amplo. Devemos esperar mais luta, queixas e “escuridão da alma”, mas também mais reverência, intimidade e experiência da realidade espiritual de Deus. John Owen é bastante claro ao afirmar que, se os afetos do coração não estiverem envolvidos na oração, a verdadeira transformação de caráter e o crescimento em semelhança com Cristo são impossíveis. E não podemos nos contentar com menos.

Um padrão para a oração diária Portanto, a questão mais prática de todas é: “Como gastar tempo de fato em oração?”. Um livro de grande ajuda, My path of prayer [Meu caminho de oração], contém uma série de ensaios bem curtos, de autoria de vários líderes cristãos, em que muitos deles relatam o próprio padrão de oração diária.21 Um dos colaboradores, Selwyn Hughes, fez a seguinte descrição da própria vida de oração: depois de se levantar pela manhã, ele costumava orar assim que possível. Lia uma passagem das Escrituras e meditava sobre ela, incluindo um salmo, se houvesse tempo. Em seguida separava um momento para “aquietar a mente” e lembrar-se tanto da presença de Deus quanto do privilégio e do poder da oração. Isso feito, punha-se a orar, começando pela adoração, o louvor e a ação de graças a Deus. Depois disso, escreve, passava para “a oração em favor da minha condição espiritual pessoal”, com isso estava se referindo ao autoexame, à confissão e ao arrependimento. Fazia então o que temos chamado de oração de petição por si próprio, pelos conhecidos, pela igreja e pelo mundo. No final, conta ele, terminava aquietando outra vez a mente e o coração para se certificar de que ouvira o que Deus queria que ele aprendesse com esse tempo de meditação e oração.22 O relato impressiona pelo fato de não ser muito original. Surpreende por se assemelhar muito às descrições de oração diária que, pelo que vimos, foram feitas por vários mestres, incluindo Martinho Lutero. Por conseguinte, acho que podemos traçar um padrão de oração diária com certa confiança de que ele servirá a muitas pessoas, sempre lembrando que nem os detalhes nem a ordem que ofereço estão gravados em pedra ou na Bíblia, ou pertencem a alguma tradição religiosa em particular. Sugiro esta estrutura — evocação, meditação, orar a Palavra, oração livre e contemplação. Evocação. Evocar significa “trazer à mente”, embora também possa incluir invocação, o clamor a Deus. Existe um entendimento praticamente universal de que a oração deva ser iniciada pela “reflexão sobre aquele a quem você estará se dirigindo, sobre o que ele fez para lhe dar acesso a si mesmo [...] sobre como manter a relação com ele [...] [e] sobre o fato verdadeiramente impressionante de que, por intermédio de sua Palavra e Espírito, o senhor Jesus está edificando uma amizade com você”.23 Um dos modos de fazer isso é recapitulando mentalmente a teologia trinitária da oração. Deus agora é seu Pai e está comprometido com o seu bem. Jesus lhe concede acesso ao trono universal por ser seu mediador, advogado e sacerdote. O Espírito Santo é o próprio Deus dentro de você, constrangendo-o e ajudando-o a orar de modo a poder saber que, se você está orando, Deus o está ouvindo. Pondere brevemente nos versículos que lhe falam ao coração acerca dessas verdades, muitos dos quais já foram discutidos neste livro. Ou você pode ler um dos salmos tradicionais utilizados na adoração para entrar na presença de Deus, como o salmo 95. Outro método é escolher uma das orações da igreja já testadas pelo tempo, como as da coletânea de Thomas Cranmer, para usar como uma espécie de invocação e assim iniciar seu período de oração.24 Leve não mais do que alguns minutos para o que estamos chamando de evocação. Meditação. Para responder a Deus em oração, devemos ouvir sua Palavra. Isso implica reservar tempo para meditar sobre alguma passagem da Bíblia como uma ponte para a oração. Essa não é uma prática que normalmente enriquece nossa vida de oração da noite para o dia. Quanto mais você tiver lido e entendido a Bíblia no decorrer dos anos, muito mais fácil se tornará meditar após a leitura bíblica. O estudo bíblico sério deve ser feito a fim de fomentar o crescimento do cristão, mas é um erro passar a maior parte do tempo diário com Deus em um minucioso estudo interpretativo da Bíblia. Isso lhe deixa pouco tempo e talvez nenhuma propensão para meditar e orar. Para quem está se iniciando na vida cristã, portanto, seria melhor reservar algum período regular — fora o período de oração diária — para um estudo sério da Bíblia. Desse modo ela pouco a pouco se tornará menos uma mistura confusa de ideias, e mais uma leitura fácil e útil como base para a meditação diária. Um modo de praticar esse tipo de estudo sério é ler a Bíblia inteira uma vez, lentamente, talvez um capítulo por dia, percorrendo-a toda em três anos mais ou menos e usando um bom comentário sucinto, de um volume, como o New Bible commentary, para fazer isso, tomando notas em um diário à medida que for avançando.25 Enquanto se dedica a esse estudo, você pode marcar alguns capítulos para desenvolver melhor a reflexão. Então, na oração diária, poderá voltar a esses capítulos para fazer uma leitura reflexiva e meditação nos moldes que temos discutido aqui. A ordem concreta de sua devoção diária seria, então, mais ou menos assim: primeiro a evocação, depois a leitura bíblica e a meditação, e em seguida a oração. Orando a Palavra. De Martinho Lutero extraímos um passo importante na oração diária, com frequência negligenciado. Depois de meditar sobre as Escrituras, Lutero reservava um tempo para “orar o texto” antes de prosseguir para uma oração mais livre. A meditação, como temos dito, não é a oração em si. Ela é uma forma de reflexão e concentração. Quando o salmista diz “Volta-te para Deus, ó minha alma”, está se referindo a esse tipo de inclinação do coração que é a meditação. Contudo, se você usar a abordagem de Lutero para a meditação — descobrir alguma coisa no texto que sirva como base para o louvor, o arrependimento e a aspiração — a meditação em si poderá ser imediatamente convertida em oração. Os salmos também têm uma forma tal que lhes permite serem convertidos com relativa facilidade em orações, e de retornarem para Deus na forma de oração. “Orar os salmos” é um modo importante e tradicional de orar a Palavra (veja a seguir mais algumas ideias a esse respeito). O modo predileto de Lutero para orar um texto das Escrituras já foi tratado nesta obra. Ele aconselha à pessoa que ora que parafreseie cada petição da Oração do Senhor com as próprias palavras, incluindo as preocupações que lhe vão no coração naquele dia. Creio que essa talvez seja a melhor maneira de estabelecer uma ponte entre Palavra e oração, porque, claro, a Oração do Senhor é o modelo abrangente do próprio Jesus. Aconselho que se adote essa prática ao menos uma vez por semana como parte desse passo em seu padrão de oração diária. Oração livre. Nesse momento simplesmente derramamos o coração em oração. No entanto, quase todos os guias de oração mais sérios nos lembram da necessidade de equilibrar nossas orações entre as três formas — adoração e ação de graças, confissão e arrependimento, petição e intercessão. Esse equilíbrio não precisa ser rígido, embora possa ser uma boa disciplina criar o hábito de repassálas em uma ordem que funcione bem para você. Aqui também é onde as listas com motivos e preocupações de oração podem ajudar, desde que tenhamos em mente a advertência de J. I. Packer de que a oração de petição só é poderosa e transforma vidas se não repassarmos apressados uma “lista de supermercado” de pedidos, mas sim elevarmos cada causa a Deus com motivação teológica e autoexame. Acima de tudo, para os iniciantes pode ser muito útil usar uma obra antiga de Matthew Henry, A method for prayer, with Scripture expressions, proper to be used under each head [Um método de oração com expressões da Escritura apropriadas para ser usadas sob cada título].26 Como já observamos, Henry extrai das Escrituras centenas de orações e então as organiza e classifica debaixo de subtítulos dos títulos mais abrangentes: louvor, confissão, petição, ação de graças, intercessão e conclusão. Se achar que seus períodos de oração livre estagnaram, o livro de Henry o suprirá com uma quantidade quase infinita de material útil. Contemplação. Já gastamos muito tempo falando sobre o que queremos e não queremos dizer por contemplação. Edwards descreveu a contemplação como os momentos em que não só sabemos que Deus é santo, mas também sentimos — “vemos” e “experimentamos” — que ele assim o é em nosso coração. Lutero a descreveu como um tempo em que ele sentia estar se “perdendo” em algum aspecto da verdade ou do caráter de Deus. No original alemão, ele diz literalmente que às vezes, quando estava envolvido em sua prática de oração, sentia que “seus pensamentos saíam para fazer um passeio”. Os pensamentos sobre Deus se tornavam “grandes” e impactantes. Então ele fazia uma pausa e se permitia um tempo para seguir a condução do Espírito. Ele escreveu:

Com frequência acontece de eu me perder [...] em uma petição da Oração do Senhor, e então abro mão de todas as outras seis. Quando tais pensamentos ricos e bons sobrevêm, a pessoa deve [...] dar-lhes ouvidos em silêncio e de modo algum reprimi-los. Pois o próprio Espírito Santo está pregando aqui, e uma palavra do seu sermão é melhor do que milhares de nossas próprias orações. [...] [Assim,] se o Espírito Santo vier e começar a pregar ao seu coração, dando-lhe pensamentos ricos e iluminados [...] aquiete-se e ouça-o.27

Como vimos ao estudar os ensinamentos de John Owen sobre a meditação, não devemos presumir que, depois de seguir certos passos, necessariamente encontraremos nosso coração e afetos envolvidos, e o Espírito Santo abrindo nosso pensamento de novas maneiras, como Lutero descreve. Essa não é a norma para a maioria das pessoas na maior parte das vezes. Podemos começar e terminar nosso tempo de oração com um senso de aridez espiritual ou mesmo da ausência do Senhor. Nesse caso, esse momento final da “contemplação” significaria captar o melhor pensamento que recebemos sobre Deus, então louválo e agradecê-lo por ele e por quem ele é, e, por fim, pedir-lhe com toda sinceridade que se aproxime e nos mostre sua face no seu devido tempo. Seguem agora dois planos de oração diária: um, mais completo e desafiador; outro, mais simples para quem está começando. Não se deixe intimidar por eles. Siga os passos do esquema — abordagem (evocação), meditação, orando a Palavra, oração livre, contemplação — sem a obrigação de realizar todas as propostas específicas nem de responder todas as perguntas correspondentes a cada parte. A oração se desenvolverá e o envolverá. Alan Jacobs, The “Book of common prayer”: a biography (Princeton: Princeton University Press, 2013), p. 24. Jacobs baseia-se em Eamon Duffy, The stripping of the altars: traditional religion in England c. 1400-c. 1580 (New Haven: Yale University Press, 1992). Edgar C. S. Gloucester, org., The first and second prayer books of Edward VI (Wildside Press, reimpr. da edição de 1910), p. 3. Ibidem, p. 8. Jacobs, The “Book of common prayer”, p. 24-7. Traduções para o inglês podem ser encontradas em Ensie Anne McKee, John Calvin: writings on pastoral piety (Mahwah: Paulist Press, 2001), p. 210-7. McNeill, Calvin: Institutes, 3.20.50., p. 917-8. Calvino acrescenta, contudo, que as horas oficiais da oração diária não deveriam se tornar “uma observância supersticiosa [...] como de quem salda uma dívida com Deus” [edições em português: João Calvino, As institutas, tradução de Waldyr Carvalho Luz (São Paulo: Cultura Cristã, 2006), 4 vols., e A instituição da religião cristã, tradução de Carlos Eduardo Oliveira; José Carlos Estêvão (São Paulo: Ed. Unesp, 2008)]. Existem diversas versões on-line do calendário. Veja http://www.mcheyne.info/calendar.pdf. Veja em Matthew M. Boulton, Life in God: John Calvin, practical formation, and the future of Protestant theology (Grand Rapids: Eerdmans, 2011) uma extensa discussão de que as práticas formativas cristãs de Calvino representaram uma espécie de “monasticismo leigo”. Isso é de particular interesse à luz do que hoje é chamado de novo monasticismo ou monasticismo leigo. O ideal monástico original defendia um modo de trabalho e vida diários completamente enquadrados nas práticas cristãs da oração, da leitura e da instrução bíblicas, do cântico e da recitação de salmos e da adoração coletiva. Isso costumava significar interromper a lida cotidiana todos os dias para observância de horários fixos tanto para a oração privada quanto para a adoração comunitária. Os monges também se sujeitavam à prestação de contas muito rígida de suas vidas uns aos outros, bem como a padrões de vida modestos e a um compromisso de servir ao próximo. O novo monasticismo tem crescido em grande parte graças a evangélicos insatisfeitos com a vida e a prática da igreja atual. Visa criar um novo monasticismo leigo, não exigindo que os membros deixem o trabalho ou a vida secular, ou que vivam literalmente debaixo do mesmo teto, mas, ainda assim, chamando-os a viver em estreita proximidade geográfica, tendo em vista a prestação de contas uns aos outros, a preocupação com os marginalizados e as práticas da tradição contemplativa que incluem a oração litúrgica diária comum em horários fixos. Uma das principais razões dadas para o movimento é a morte da cristandade. À medida que nossa cultura se torna mais pós-cristã, os crentes necessitam estar mais imersos em práticas cristãs comunitárias a fim de não assimilar demais os valores da cultura circundante. Veja Jonathan WilsonHartgrove, New monasticism: what it has to say to today’s church (Brazos, 2008), e Rob Moll, “The new monasticism”, Christianity Today, April 24, 2008. Os promotores do novo monasticismo leigo quase sempre recorrem a fontes históricas católicas ou anabatistas, e isso, até certo ponto, acontece porque os protestantes anabatistas têm atuado há séculos como minorias sob combate, e pelo ideal monástico original haver sido herdado do catolicismo. Mas é discutível que Calvino tenha proposto o primeiro esforço sério de adotar um monasticismo leigo. Seu programa era muito mais extenso do que o de Lutero. Como explica Boulton, Calvino estava preocupado em “reformar” uma cidade inteira, no meio da Europa católica medieval, segundo os contornos do que ele considerava a fé cristã bíblica. Portanto, ele oferece muitos recursos para quem busca desenvolver uma comunidade cristã espiritualmente formativa hoje no ocidente pós-moderno. Veja também Scott Manetsch, Calvin’s company of pastors (New York: Oxford University Press, 2012). Quiet time: an InterVarsity guidebook for daily devotions (Downers Grove: InterVarsity Press, 1945). Embora os autores sejam apresentados como Equipe da InterVarsity, o livro foi compilado dos escritos de muitos missionários evangélicos de longa data, incluindo o bispo Frank Houghton, W. Graham Scroggie, Paget Wilkes e a sra. Harry Strachan. C. Stacey Woods, fundador australiano-canadense da InterVarsity dos Estados Unidos, editou o livro britânico para livrá-lo dos “anglicismos” e publicou-o nos Estados Unidos. Veja A. Donald MacLeod, C. Stacey Woods and the Evangelical rediscovery of the university (Downers Grove: InterVarsity, 2007), p. 107. Cf.: um dos melhores foi Appointment with God: a practical approach to developing a personal relationship with God (The Navigators, 1973). Quiet time, edição revista, 1976 (InterVarsity Press), p. 21. Ibidem, p. 15-6. Mais adiante no livreto, um esboço diferente de oração é apresentado — ação de graças, louvor e adoração usando os nomes de Deus, confissão, intercessão por outros e entrega do novo dia a Deus (p. 21). Isso reflete o fato de que embora seja bastante curto, o livro é uma compilação de reflexões sobre devoções diárias de sete autores diferentes. Appointment with God, p. 16. Phyllis Tickle, The divine hours, prayers for springtime: a manual for prayer (Image, 2006); The divine hours, prayers for summertime: a manual for prayer (Image, 2006); The divine hours, prayers for autumn and wintertime: a manual for prayer (Image, 2006). Veja John Bunyan, Prayer (Carlisle: Banner of Truth, 1965). Owen, Works, vol. 4, p. 348. Veja o capítulo inteiro de Owen “Prescribed forms of prayer examined”, in: Works, vol. 4, p. 338-51. Horton, Calvin on the Christian life, p. 154. Luther, “A simple way to pray”, p. 193 [edição em português: Lutero, Como orar (São Leopoldo/Porto Alegre: Sinodal/Concórdia, 1999). Arthur G. Bennett, The valley of vision: a collection of Puritan prayers and devotions (Carlisle: Banner of Truth, 1975). David Hanes, org., My path of prayer (Wales: Crossway UK Books, 1991). Ibidem, p. 57-65. Packer; Nystrom, Praying: finding our way, p. 286. Veja Barbee; Zahl, Collects of Thomas Cranmer. A obra oferece não só um ano (52 semanas) de orações de Cranmer, mas também uma breve explanação e meditação sobre cada uma delas. Isso torna o livro extremamente útil para o momento inicial da oração diária de “evocação/invocação”. D. A. Carson et. al., eds., New Bible commentary, 21st century edition (Downers Grove: InterVarsity Press, 1994) [edição em português: Comentário bíblico Vida Nova (São Paulo: Vida Nova, 2009)]. Henry, A method for prayer. Veja também uma edição menos extensa: Henry, A way to pray. O responsável pela primeira edição, Ligon Duncon, descreve em linhas gerais o livro inteiro em um apêndice. Só o apêndice já oferece grande quantidade de ideias específicas sobre como adorar, confessar, agradecer, suplicar e interceder a Deus. Para usar o livro em oração, você só precisa personalizar os cabeçalhos e orar com as próprias palavras e com base em suas necessidades específicas. Extraído de “A simple way to pray”, de Lutero, citado em Packer; Nystrom, Praying: finding our way, p. 288. Packer aqui cita com base na tradução de Walter Trobisch, em seu livrete e clássico Martin Luther’s quiet time.$conteudo$
    )
    returning id into v_aula_id;

    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Keller insiste que a oração espontânea ao longo do dia nunca se desenvolve sem a disciplina de uma oração regular e diária, e propõe orar mais de uma vez por dia em horários determinados. Como está hoje o seu ritmo de oração diária, e que estrutura concreta de horário você poderia adotar para que ela deixe de depender só do impulso do momento?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O padrão que Keller sugere passa por evocação, meditação na Palavra, orar a Palavra, oração livre e contemplação — começando por trazer Deus à mente antes de despejar pedidos. Qual desses passos costuma faltar na sua oração, e como incluí-lo poderia mudar a qualidade do seu encontro com Deus?$p$, 'reflexao', null),
